#!/bin/bash
# sampleCurlWriteCommands.sh — Example write operations (POST, PUT, PATCH, DELETE) for this Gilhari service
# Generated by orm_skyway.py
#
# All curl commands below are uncommented to allow direct execution.
# Each command WILL modify data in your database.
# For read-only (GET) operations, use sampleCurlCommands.sh instead.
#
BASE_URL="http://localhost:80/gilhari/v1"

echo "Starting write operations" > curlWrite.log

# --- Categories ---

# POST: Insert a new Categories object
echo "POST Categories" >> curlWrite.log
curl -s -X POST "$BASE_URL/Categories" -H "Content-Type: application/json" -d '{"entity": {"ID": 101, "DESCRIPTION": "Electronics Accessories", "CREATED_AT": "2026-07-17T10:00:00", "CREATED_DATE": "2026-07-17", "SORT_ORDER": 1, "IS_ACTIVE": true, "NAME": "Cables"}}' >> curlWrite.log 2>&1
echo "" >> curlWrite.log

# PUT: Update a specific Categories object (supply primary key + all attributes)
echo "PUT Categories" >> curlWrite.log
curl -s -X PUT "$BASE_URL/Categories/updateEntity" -H "Content-Type: application/json" -d '{"entity": {"ID": 101, "DESCRIPTION": "Updated Electronics Accessories", "CREATED_AT": "2026-07-17T10:00:00", "CREATED_DATE": "2026-07-17", "SORT_ORDER": 2, "IS_ACTIVE": true, "NAME": "Premium Cables"}}' >> curlWrite.log 2>&1
echo "" >> curlWrite.log

# PATCH: Bulk-update Categories objects matching a filter (returns count of updated objects)
echo "PATCH Categories" >> curlWrite.log
curl -s -X PATCH "$BASE_URL/Categories?filter=ID=101" -H "Content-Type: application/json" -d '{"newValues": ["DESCRIPTION", "Patched Accessories"]}' >> curlWrite.log 2>&1
echo "" >> curlWrite.log

# --- Suppliers ---

# POST: Insert a new Suppliers object
echo "POST Suppliers" >> curlWrite.log
curl -s -X POST "$BASE_URL/Suppliers" -H "Content-Type: application/json" -d '{"entity": {"ID": 101, "CREATED_AT": "2026-07-17T10:00:00", "RATING": 4.5, "CONTACT_EMAIL": "contact@techsupply.com", "IS_ACTIVE": true, "NAME": "TechSupply Inc"}}' >> curlWrite.log 2>&1
echo "" >> curlWrite.log

# PUT: Update a specific Suppliers object (supply primary key + all attributes)
echo "PUT Suppliers" >> curlWrite.log
curl -s -X PUT "$BASE_URL/Suppliers/updateEntity" -H "Content-Type: application/json" -d '{"entity": {"ID": 101, "CREATED_AT": "2026-07-17T10:00:00", "RATING": 4.8, "CONTACT_EMAIL": "info@techsupply.com", "IS_ACTIVE": true, "NAME": "TechSupply Global"}}' >> curlWrite.log 2>&1
echo "" >> curlWrite.log

# PATCH: Bulk-update Suppliers objects matching a filter (returns count of updated objects)
echo "PATCH Suppliers" >> curlWrite.log
curl -s -X PATCH "$BASE_URL/Suppliers?filter=ID=101" -H "Content-Type: application/json" -d '{"newValues": ["RATING", 5.0]}' >> curlWrite.log 2>&1
