# --- Products ---

# POST: Insert a new Products object
echo "POST Products" >> curlWrite.log
curl -s -X POST "$BASE_URL/Products" -H "Content-Type: application/json" -d '{"entity": {"STOCK_COUNT": 50, "PRICE": 15.99, "NOTES": "High quality HDMI cable", "AVAILABLE_TIME": "12:00:00", "ID": 101, "IN_STOCK": true, "CATEGORY_ID": 101, "WEIGHT_KG": 0.2, "LAST_UPDATED": "2026-07-17T10:00:00", "SUPPLIER_ID": 101, "NAME": "HDMI Cable"}}' >> curlWrite.log 2>&1
echo "" >> curlWrite.log

# PUT: Update a specific Products object (supply primary key + all attributes)
echo "PUT Products" >> curlWrite.log
curl -s -X PUT "$BASE_URL/Products/updateEntity" -H "Content-Type: application/json" -d '{"entity": {"STOCK_COUNT": 40, "PRICE": 14.99, "NOTES": "Discounted HDMI cable", "AVAILABLE_TIME": "12:00:00", "ID": 101, "IN_STOCK": true, "CATEGORY_ID": 101, "WEIGHT_KG": 0.2, "LAST_UPDATED": "2026-07-17T11:00:00", "SUPPLIER_ID": 101, "NAME": "HDMI Cable 2.0"}}' >> curlWrite.log 2>&1
echo "" >> curlWrite.log

# PATCH: Bulk-update Products objects matching a filter (returns count of updated objects)
echo "PATCH Products" >> curlWrite.log
curl -s -X PATCH "$BASE_URL/Products?filter=ID=101" -H "Content-Type: application/json" -d '{"newValues": ["STOCK_COUNT", 35]}' >> curlWrite.log 2>&1
echo "" >> curlWrite.log

# --- CLEANUP (Deletes) ---
# Note: Products must be deleted before Categories/Suppliers due to foreign keys.

# DELETE: Delete Products objects matching a filter
echo "DELETE Products" >> curlWrite.log
curl -s -X DELETE "$BASE_URL/Products?filter=ID=101" >> curlWrite.log 2>&1
echo "" >> curlWrite.log

# DELETE: Delete Suppliers objects matching a filter
echo "DELETE Suppliers" >> curlWrite.log
curl -s -X DELETE "$BASE_URL/Suppliers?filter=ID=101" >> curlWrite.log 2>&1
